) -> Self {
    Self {
        next_review_id: Arc::new(AtomicU64::new(1)),
        store,
        profile_store,
    }
}

pub fn review(
    &self,
    source: impl Into<ReviewSourceLike>,
) -> Result<ReviewSession, ReviewSessionError> {
