#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct ReviewSessionId(pub(super) String);

impl ReviewSessionId {
    pub fn new(id: impl Into<String>) -> Result<Self, ReviewSessionError> {
        let id = id.into();
        if id.trim().is_empty() {
