import { describe, it } from "node:test";
import assert from "node:assert/strict";

import {
  projectReviewComments,
  projectSarif,
  type ReviewFinding,
} from "./index.js";

const finding: ReviewFinding = {
  id: "finding-1",
  severity: "error",
  category: "bug",
  title: "Unsafe unwrap",
  message: "The changed code can panic when the input is missing.",
  confidence: 0.92,
  location: {
    path: "src/lib.rs",
    revision: "head",
    startLine: 12,
    endLine: 14,
    side: "additions",
    providerAnchor: {
      gitlabLineCode: "abc",
    },
  },
  suggestedFix: {
    description: "Return an error instead of unwrapping.",
  },
};

describe("review projections", () => {
  it("projects provider-neutral findings into host review comments", () => {
    const comments = projectReviewComments([finding]);

    assert.deepEqual(comments, [
      {
        sourceFindingId: "finding-1",
        path: "src/lib.rs",
        line: 14,
        startLine: 12,
        side: "additions",
        severity: "error",
        title: "Unsafe unwrap",
        providerAnchor: {
          gitlabLineCode: "abc",
        },
        body: [
          "### Unsafe unwrap",
          "",
          "The changed code can panic when the input is missing.",
          "",
          "Severity: error",
          "Category: bug",
          "Confidence: 92%",
          "",
          "Suggested fix:",
          "Return an error instead of unwrapping.",
        ].join("\n"),
      },
    ]);
  });

it("skips unanchored comments unless requested", () => {
  const unanchored = {
    ...finding,
    id: "finding-2",
    location: undefined,
  };

  assert.deepEqual(projectReviewComments([unanchored]), []);
  assert.equal(
    projectReviewComments([unanchored], { includeUnanchored: true })[0]
      .sourceFindingId,
    "finding-2",
  );
});

  it("projects findings into SARIF", () => {
    const sarif = projectSarif([finding], { toolName: "Muzen Test" });

    assert.deepEqual(sarif, {
      version: "2.1.0",
      runs: [
        {
          tool: {
            driver: {
              name: "Muzen Test",
              rules: [
                {
                  id: "bug",
                  name: "bug",
                  shortDescription: { text: "bug finding" },
                },
              ],
            },
          },
          results: [
            {
              ruleId: "bug",
              level: "error",
              message: {
                text:
                  "Unsafe unwrap\n\nThe changed code can panic when the input is missing.",
              },
              locations: [
                {
                  physicalLocation: {
                    artifactLocation: { uri: "src/lib.rs" },
                    region: {
                      startLine: 12,
                      endLine: 14,
                      startColumn: undefined,
                      endColumn: undefined,
                    },
                  },
                },
              ],
              properties: {
                sourceFindingId: "finding-1",
                category: "bug",
                confidence: 0.92,
              },
            },
          ],
        },
      ],
    });
  });
});

import { createMuzen, local, type ReviewEvent } from "@muzen/sdk";

const runnerPath = process.env.MUZEN_RUNNER_PATH;
const repo = process.argv[2] ?? ".";
const changedFiles = process.argv.slice(3);
const after = process.env.MUZEN_AFTER_CURSOR ?? null;

const muzen = await createMuzen({ runnerPath });

try {
  const review = await muzen.review(
    local(repo, {
      changedFiles,
    }),
  );

  let eventCount = 0;
  for await (const event of review.events({ after })) {
    eventCount += 1;
    printEvent(event);
  }

  const result = await review.wait();
  console.log(`review ${review.id} replayed ${eventCount} event(s)`);
  console.log(result.conclusion);
  console.log(result.summary);
} finally {
  await muzen.close();
}

function printEvent(event: ReviewEvent): void {
  const prefix = `${event.cursor} ${event.type}`;
  if (event.payload === undefined || event.payload === null) {
    console.log(prefix);
    return;
  }
  console.log(`${prefix} ${JSON.stringify(event.payload)}`);
}

use std::sync::Arc;

use async_trait::async_trait;
use tokio_util::sync::CancellationToken;

use crate::runtime::contracts::{
    CacheStatus, RuntimeError, RuntimeResult, ToolArgs, ToolInvocation, ToolProviderId,
    ToolResultEnvelope,
};

use super::engine::ToolEngine;
use super::registry::{JsonRpcToolRequest, JsonRpcToolTransport, ToolDefinition};

#[async_trait]
pub(crate) trait ToolProvider: Send + Sync {
    fn id(&self) -> ToolProviderId;
    fn accepts(&self, definition: &ToolDefinition) -> bool;

    async fn execute(
        &self,
        engine: &ToolEngine,
        invocation: ToolInvocation,
        cancel: CancellationToken,
        cache_status: CacheStatus,
    ) -> RuntimeResult<ToolResultEnvelope>;
}

#[derive(Debug, Clone, Default)]
pub(crate) struct BuiltinReviewToolProvider;

#[async_trait]
impl ToolProvider for BuiltinReviewToolProvider {
    fn id(&self) -> ToolProviderId {
        ToolProviderId::builtin_review()
    }

    fn accepts(&self, definition: &ToolDefinition) -> bool {
        definition.provider_id == self.id() && definition.builtin.is_some()
    }

    async fn execute(
        &self,
        engine: &ToolEngine,
        invocation: ToolInvocation,
        cancel: CancellationToken,
        cache_status: CacheStatus,
    ) -> RuntimeResult<ToolResultEnvelope> {
        Ok(engine
            .execute_builtin_tool(invocation, cancel, cache_status)
            .await)
    }
}

#[derive(Debug, Clone, Default)]
pub(crate) struct InProcessToolProvider;

#[async_trait]

impl ToolProvider for InProcessToolProvider {
    fn id(&self) -> ToolProviderId {
        ToolProviderId::in_process()
    }

    fn accepts(&self, definition: &ToolDefinition) -> bool {
        definition.provider_id == self.id() && definition.builtin.is_none()
    }

    async fn execute(
        &self,
        engine: &ToolEngine,
        invocation: ToolInvocation,
        cancel: CancellationToken,
        cache_status: CacheStatus,
    ) -> RuntimeResult<ToolResultEnvelope> {
        Ok(engine
            .execute_in_process_tool(invocation, cancel, cache_status)
            .await)
    }
}

pub(crate) struct JsonRpcToolProvider {
    provider_id: ToolProviderId,
    transport: Arc<dyn JsonRpcToolTransport>,
}

impl JsonRpcToolProvider {
    pub(crate) fn new(
        provider_id: ToolProviderId,
        transport: Arc<dyn JsonRpcToolTransport>,
    ) -> Self {
        Self {
            provider_id,
            transport,
        }
    }
}

impl std::fmt::Debug for JsonRpcToolProvider {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("JsonRpcToolProvider")
            .field("provider_id", &self.provider_id)
            .finish_non_exhaustive()
    }
}

#[async_trait]
impl ToolProvider for JsonRpcToolProvider {
    fn id(&self) -> ToolProviderId {
        self.provider_id.clone()
    }

    fn accepts(&self, definition: &ToolDefinition) -> bool {
        definition.provider_id == self.provider_id
            && definition.builtin.is_none()
            && definition.handler.is_none()
    }

    async fn execute(
        &self,
        engine: &ToolEngine,
        invocation: ToolInvocation,
        cancel: CancellationToken,
        cache_status: CacheStatus,
    ) -> RuntimeResult<ToolResultEnvelope> {
        let ToolArgs::Raw(arguments) = invocation.args else {
            return Err(RuntimeError::InvalidInput(
                "JSON-RPC tool requires raw JSON arguments".to_string(),
            ));
        };
        let provider_id = self.provider_id.clone();
        let call_id = invocation.call_id;
        let tool_id = invocation.tool_id;
        let provider_resources = engine
            .registry
            .definition(&tool_id)
            .map(|definition| definition.provider_resources.clone())
            .unwrap_or_default();
        let output = self
            .transport
            .call(
                JsonRpcToolRequest {
                    provider_id: provider_id.clone(),
                    session_id: invocation.session_id,
                    turn_id: invocation.turn_id,
                    call_id: call_id.clone(),
                    tool_id: tool_id.clone(),
                    snapshot_id: engine.snapshot.snapshot_id.clone(),
                    provider_resources,
                    arguments,
                },
                cancel,
            )
            .await?;
        Ok(engine.provider_output_result(
            call_id,
            tool_id,
            provider_id,
            cache_status,
            &invocation.capabilities,
            output,
        ))
    }
}

