        self.transcript
            .iter()
            .filter(|item| matches!(item, ReviewTranscriptItem::ToolResult { .. }))
            .count()
    }

    pub fn tool_call_id(&self, suffix: impl AsRef<str>) -> String {
        format!("{}-{}-{}", self.session_id, self.turn, suffix.as_ref())
    }
