    return Response.json({
      artifact: {
        artifactId: "artifact-1",
        bytes: 4,
        contentHash: "hash",
        content: "data",
      },
    });
  }
  if (
    url.pathname ===
      "/v1/reviews/review-remote-1/artifacts/export" &&
