function completedResult(findings: ReviewFinding[]): ReviewResult {
  return {
    reviewId: "review-1",
    sessionId: "review-1",
    status: "completed",
    conclusion: findings.length > 0 ? "commented" : "approved",
    summary: "Review completed.",
    findings,
    coverage: {
      filesConsidered: 1,
      filesReviewed: 1,
      filesSkipped: 0,
    },
  };
}

function finding(title: string, message: string): ReviewFinding {
  return {
    id: title.toLowerCase().replace(/\W+/g, "-"),
    title,
    message,
    category: "security",
    severity: "error",
    confidence: 0.9,
    validationStatus: "validated",
    location: {
      path: "app/jobs/regular/retrieve_topic.rb",
      startLine: 10,
      endLine: 10,
    },
    evidence: [],
    discoveredBy: ["security"],
    validatedBy: [],
  };
}

function fileReviewEvent(
  path: string,
  verdict: string,
  options: { findingId?: string } = {},
): ReviewEvent {
  return event({
    artifactCreated: {
      toolId: "record_file_review",
      details: {
        findingId: options.findingId,
        path,
        verdict,
      },
    },
  });
}

function sessionFinishedEvent(sessionId: string, status: string): ReviewEvent {
  return event({
    sessionFinished: {
      sessionId,
      status,
    },
  });
}

function listChangedFilesEvent(changedFiles: string[]): ReviewEvent {
  return event({
    artifactCreated: {
      toolId: "list_changed_files",
      details: { changedFiles },
    },
  });
}

function modelFailedEvent(
  sessionId: string,
  attempt: number,
  retrying: boolean,
  message: string,
): ReviewEvent {
  return event({
    context: { sessionId },
    modelFailed: {
      attempt,
      message,
      retrying,
      sessionId,
      turn: 0,
    },
  });
}

function toolFailedEvent(
  sessionId: string,
  toolId: string,
  errorCode: string,
  details?: Record<string, unknown>,
): ReviewEvent {
  return event({
    context: { sessionId },
    toolCallCompleted: {
      toolId,
      ok: false,
      errorCode,
      details,
    },
  });
}

function event(payload: unknown): ReviewEvent {
  return {
    cursor: Math.random().toString(),
    reviewId: "review-1",
    timestampUtc: "2026-06-06T00:00:00.000Z",
    type: "runner.event",
    payload,
  };
}

