        }),
        crate::reviewer::ReviewTranscriptItem::ToolResult {
            call_id,
            tool_id,
            ok,
            artifact_id,
            data,
            error_code,
        } => json!({
            "kind": "tool_result",
            "callId": call_id,
            "toolId": tool_id,
