    .set_model_profile(
        "default",
        ModelProfileInput {
            provider: ModelProviderKind::OpenaiCompatible,
            model: "gpt-5.1".to_string(),
            secret_ref: Some("vault://workspaces/acme/models/default".to_string()),
            base_url: Some("https://models.example.test".to_string()),
            routing: BTreeMap::new(),
        },
